continuous = [0]+list(range(10,20))
centers=np.array([-.1]+[.5]*9+[5.]*10)
scales=np.array([4.1]+[.5]*9+[5.]*10)
knots={j:([0.,-2.,2.] if j==0 else ([5.,2.,8.,4.,6.,7.,9.] if j==12 else [5.,2.5,7.5])) for j in continuous}
trans={}
for j in continuous:
 lo,hi=(-4.2,4.) if j==0 else (0.,10.)
 u=np.linspace(lo,hi,40001)
 Q=np.column_stack([np.ones(len(u)),(u-centers[j])/scales[j]]+[np.maximum(u-k,0)/scales[j] for k in knots[j]])
 trans[j]=np.linalg.inv(np.linalg.cholesky(Q.T@Q/len(u)).T)
def basis(X):
 U={}
 for j in range(p):
  if j in continuous:
   Q=np.column_stack([np.ones(len(X)),(X[:,j]-centers[j])/scales[j]]+[np.maximum(X[:,j]-k,0)/scales[j] for k in knots[j]])
   U[j]=(Q@trans[j])[:,1:]
  else:
   U[j]=(2*X[:,j]-1).reshape(-1,1)
 return U
descs=[('constant',)]
for j in range(p):
 for a in range(1+len(knots[j]) if j in continuous else 1):
  descs.append((j,a))
nmain=len(descs)
for j in range(p):
 for k in range(j+1,p):
  nj=1+len(knots[j]) if j in continuous else 1
  nk=1+len(knots[k]) if k in continuous else 1
  for a in range(nj):
   for b in range(nk):
    use=(a<=1 and b<=1)
    if j==12 or k==12:
     c,d=(a,b) if j==12 else (b,a)
     use=use or (c<=3 and d<=1)
    if j==0:
     use=use or (a<=3 and b==0)
    if use:
     descs.append((j,k,a,b))
def matrix(X,which=None):
 U=basis(X)
 dd=descs if which is None else [descs[q] for q in which]
 cols=[]
 for d in dd:
  if len(d)==1:
   cols.append(np.ones(len(X)))
  elif len(d)==2:
   j,a=d
   cols.append(U[j][:,a])
  else:
   j,k,a,b=d
   cols.append(U[j][:,a]*U[k][:,b])
 return np.column_stack(cols)
